"""Read-merge-write of _parts/animator_manifest.json: replaces ONLY the top-level "soul" key; every other key
("effects", "run_bike", ...) is read and written back untouched (verified before the write)."""
import json, os, sys
from soul_lib import PIX, SOUL, rel
ITEMS = ['spotted', 'battle_feedback', 'trail_buddy', 'ambient', 'lap_nap']
MAN = f'{PIX}/_parts/animator_manifest.json'

def build():
    soul = {'_about': 'Soul pass (SOUL_PLAYBOOK). Per item: animations (frames/size/timing/anchors/paths) + hook specs for Coder. '
                      'Generated by soul/_tools/write_manifest.py; validate with soul/_tools/validate_soul.py.',
            'root': rel(SOUL)}
    for it in ITEMS:
        d = f'{SOUL}/{it}'
        e = {'readme': rel(f'{d}/README.md'), 'animations': json.load(open(f'{d}/_meta.json'))}
        if os.path.exists(f'{d}/hook_specs.json'): e['hook_specs'] = json.load(open(f'{d}/hook_specs.json'))
        if os.path.isdir(f'{d}/previews'): e['previews'] = sorted(rel(f'{d}/previews/{f}') for f in os.listdir(f'{d}/previews'))
        soul[it] = e
    return soul

def main():
    before = json.load(open(MAN))
    others = {k: json.dumps(v, sort_keys=True) for k, v in before.items() if k != 'soul'}
    before['soul'] = build()
    tmp = MAN + '.tmp'
    json.dump(before, open(tmp, 'w'), indent=1)
    after = json.load(open(tmp))
    assert {k: json.dumps(v, sort_keys=True) for k, v in after.items() if k != 'soul'} == others, 'non-soul keys changed!'
    os.replace(tmp, MAN)
    print('manifest keys:', list(after), '| soul items:', [k for k in after['soul'] if not k.startswith('_') and k != 'root'])

if __name__ == '__main__':
    main()
